contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 blockNoParam) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();
        uint256 afterBal = address(c).balance;

        assert(
            reverted
                ? (afterTime == beforeTime && afterBal == beforeBal)
                : (
                    afterTime == block.timestamp
                        && afterTime > beforeTime
                        && afterBal == beforeBal + amount - (beforeBal + amount) * 0
                )
        );
    }

    receive() external payable {}
}

