contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Ensure the call is acceptable: must be strictly later than the previously recorded timestamp.
        // If pastBlockTime is already at/after current block.timestamp, make a benign call to reset it
        // to an earlier timestamp so the deciding call has a valid, strictly-later timestamp.
        if (c.pastBlockTime() >= block.timestamp) {
            c.fallback{value: 10 ether}();
        }

        require(block.timestamp > c.pastBlockTime(), "timestamp not strictly later");

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted);

        uint256 afterBalance = address(c).balance;

        if (block.number % 15 == 0) {
            assert(afterBalance == 0);
        } else {
            assert(afterBalance == beforeBalance + amount);
        }

        assert(c.pastBlockTime() == block.timestamp);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Make sure the new timestamp will be strictly greater than the stored one.
        // We may need to reset a large stored value first, but since each block has a new timestamp,
        // it is enough to just wait for a larger timestamp. The checker runs this once: block.timestamp
        // is fixed. We cannot wait, so instead we ensure the stored pastBlockTime is already less than
        // block.timestamp, or we make one call that will set it to block.timestamp. If this call happens
        // and succeeds, it consumes exactly one change and makes the next call's require fail because
        // the timestamp is no longer strictly greater. So we must guarantee the first call is not needed.
        // We can require that before the call, pastBlockTime is already strictly less than block.timestamp.
        require(c.pastBlockTime() < block.timestamp, "timestamp precondition");

        uint256 beforeBalance = address(c).balance;

        (bool success, ) = address(c).call{value: amount}("");

        uint256 afterBalance = address(c).balance;

        assert(success);
        assert(c.pastBlockTime() == block.timestamp);
        if (block.number % 15 == 0) {
            assert(afterBalance == 0);
        } else {
            assert(afterBalance == beforeBalance + amount);
        }
    }

    receive() external payable {}
}

