    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint adv, uint blockNum) public payable {
        require(address(this).balance >= amount);
        require(adv > 0);

        // Try to set up a target pastBlockTime value without using it as the deciding call:
        // Only attempt to initialize through successful 10-ether calls, if possible.
        if (amount == 10 ether) {
            bool setupReverted;
            try c.fallback{value: amount}() {
                setupReverted = false;
            } catch {
                setupReverted = true;
            }
            // If the setup succeeded, the fallback requirement was met and pastBlockTime increased.
            // If it reverted, it may be because the current timestamp was not greater than the stored one;
            // the test then still exercises a potentially reverting parameter set.
        }

        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        // General rule:
        // 1) A fallback call with the wrong msg.value (not exactly 10 ether) must revert.
        // 2) A fallback call with exactly 10 ether reverts exactly when the current block.timestamp
        //    is not strictly greater than the stored pastBlockTime.
        // 3) Whenever a fallback call succeeds, pastBlockTime is updated to the current block timestamp.
        assert(
            (amount != 10 ether ? reverted : true) &&
            (amount == 10 ether ? (reverted == !(block.timestamp > beforeTime)) : true) &&
            (!reverted ? afterTime == block.timestamp : true)
        );
    }

    receive() external payable {}
}

