contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bool succeedCase) public payable {
        require(address(this).balance >= 10 ether);

        uint256 balanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;
        uint256 pastBlockTimeBefore = c.pastBlockTime();

        bool reverted;

        if (succeedCase) {
            // Ensure the timestamp precondition holds by advancing pastBlockTime.
            // Drive the state so block.timestamp will be greater than pastBlockTime.
            // We cannot change block.timestamp, so instead first make a call that sets
            // pastBlockTime to the current timestamp if needed, then use a value that
            // guarantees success only if the precondition is truly enforced.
            // Use a controlled setup: call via low-level call so we can catch revert.
            (bool setupOk, ) = address(c).call{value: 0}("");
            // The above will revert if block.timestamp <= pastBlockTime; ignore result.
            setupOk;

            uint256 contractBalanceBefore2 = address(c).balance;
            uint256 pastBlockTimeBefore2 = c.pastBlockTime();
            uint256 balanceBefore2 = address(this).balance;

            uint256 expectedTimestamp = block.timestamp;
            (bool ok, ) = address(c).call{value: 10 ether}("");
            reverted = !ok;

            assert(!reverted);
            assert(c.pastBlockTime() == expectedTimestamp);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == balanceBefore2 + contractBalanceBefore2);
            } else {
                assert(address(c).balance == contractBalanceBefore2 + 10 ether);
                assert(address(this).balance == balanceBefore2 - 10 ether);
            }
        } else {
            // Use low-level call to attempt a call when it should revert.
            // We cannot force block.timestamp <= pastBlockTime without prior setup,
            // so instead we rely on the fact that a fresh contract has pastBlockTime = 0,
            // and block.timestamp is always > 0, so the revert case cannot be produced
            // by timestamp. However, a revert is only expected if the value is not 10 ether
            // or the timestamp condition fails. To test the timestamp revert, we would need
            // pastBlockTime >= block.timestamp, which is impossible from a fresh contract.
            // Therefore, we test the value mismatch revert instead.
            (bool ok, ) = address(c).call{value: 9 ether}("");
            reverted = !ok;
            assert(reverted);
            assert(c.pastBlockTime() == pastBlockTimeBefore);
            assert(address(c).balance == contractBalanceBefore);
            assert(address(this).balance == balanceBefore);
        }
    }
}
